    changes = []  # Store segments (list of friend names visiting in each segment)
    current_segment = []
    processing_segment = True

    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '1':
            # End current segment, save it
            if current_segment:
                changes.append(current_segment)
                current_segment = []
            processing_segment = True
        else:
            # Type 2 event: friend visiting
            name = parts[1]
            current_segment.append(name)

    # Don't forget the last segment
    if current_segment:
        changes.append(current_segment)

    # Build conflict graph using bitmask
    conflict_mask = [0] * m  # conflict_mask[i] has bit j set if friend i conflicts with friend j

    for segment in changes:
        n_segment = len(segment)
        for i in range(n_segment):
            for j in range(i + 1, n_segment):
                u = int(segment[i])
                v = int(segment[j])
                conflict_mask[u] |= (1 << v)
                conflict_mask[v] |= (1 << u)

    # Find maximum independent set using bitmask enumeration
    max_happy = 0
    full = m - 1
    high = 1 << m
    for mask in range(high):
        valid = True
        for i in range(m):
            if (mask >> i) & 1:
                mask2 = mask & conflict_mask[i]
                if mask2:
                    valid = False
                    break
        if valid:
            max_happy = max(max_happy, bin(mask).count('1'))

    return str(max_happy)

