    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {}

    def grundy(n):
        if n == 0:
            return 0
        if n in memo:
            return memo[n]

        options = {grundy(n - 1)}
        if n % 2 == 1:
            # Odd: only first move is available
            pass
        else:
            # Even: split to k piles
            if k % 2 == 1:
                # k is odd -> XOR of k copies is g(n/2)
                options.add(grundy(n // 2))
            else:
                # k is even -> XOR of k copies is 0
                options.add(0)

        mex = 0
        while mex in options:
            mex += 1

        memo[n] = mex
        return mex

    xor_sum = 0
    for x in a:
        xor_sum ^= grundy(x)

    result = "Kevin" if xor_sum != 0 else "Nicky"
    return result

