    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Sort edges by weight
    sorted_edges = sorted(edges, key=lambda x: x[2])

    mst_edges = set()
    edges_by_weight = {}  # Map weight to (u, v) for retrieval

    for u, v, w in sorted_edges:
        if union(u, v):
            mst_edges.add((min(u, v), max(u, v)))
            edges_by_weight[w] = (u, v)

    # Add MST edges to a list for tree construction
    adj = [[] for _ in range(n + 1)]
    root = 1
    for u, v, w in sorted_edges:
        if union(u, v):
            # Add edge (u, v) with weight w to tree
            adj[u].append((v, w))
            adj[v].append((u, w))

    # DFS to build LCA table for maximum edge on path
    dp = [[0] * 20 for _ in range(n + 1)]
    up = [[-1] * 20 for _ in range(n + 1)]
