                up[u][i] = up[up[u][i-1]][i-1]
                w1 = dp[u][i-1]
                w2 = dp[up[u][i-1]][i-1] if up[u][i-1] != -1 else 0
                dp[u][i] = max(w1, w2)

        for v, w in adj[u]:
            if v != p:
                dfs(v, u, d + 1, w)

    dfs(root, root, 0, 0)

    # LCA and path max function
    def on_path(u, v, w_target):
