        if depth[u] < depth[v]:
            u, v = v, u

        max_on_path = 0

        # Lift u to same depth as v
        for i in range(19, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                max_on_path = max(max_on_path, dp[u][i])
                u = up[u][i]

        if u != v:
            for i in range(19, -1, -1):
