def is_valid(a):
    """Check if all piles can be emptied with given operations."""
    n = len(a)
    if n == 0:
        return True

    # Start from the rightmost pile
    ops = a[n - 1]
    for i in range(n - 2, -1, -1):
        if ops < 0:
            return False
        ops = a[i] - ops

    # Must match first pile exactly
    return ops == a[0]

def check_with_swap(arr):
    """Check if any single adjacent swap makes the array valid."""
    n = len(arr)
    if n < 2:
        return True

    for i in range(n - 1):
        b = arr[:]
        b[i], b[i+1] = b[i+1], b[i]
        if is_valid(b):
            return True
    return False

