def get_transformer_positions(transformer, step):
    """
    Get transformer's position at step (time from start at t=0)
    step corresponds to time = t + step since transformer starts at time t
    """
    x = transformer['x']
    y = transformer['y']
    d = transformer['d']
    t = transformer['t']

    if step < t:
        return None

    time_since_start = step - t
    k = time_since_start % 4

    # Based on the pattern: {(x,y),(x+d,y-d),(x+d,y),(x,y+d)}
    # At k=0: (x, y)
    # At k=1: (x+d, y-d)
    # At k=2: (x+d, y)
    # At k=3: (x, y+d)

    if k == 0:
        return (x, y, d)
    elif k == 1:
        return (x + d, y - d, d)
    elif k == 2:
        return (x + d, y, d)
    else:  # k == 3
