    """
    Compute the total energy cost at each position (i, j) for each possible step count
    step_count = i + j (time elapsed from start at (0,0))
    """
    # dp[step_count] = dictionary mapping (i, j) to list of (transformer_idx, cost)
    max_step = n + m - 2  # Maximum steps to reach (n-1, m-1)

    # MeetingTable[step][(i, j)] = total energy at step (i, j) in exactly step steps from start
    meeting_costs = {}

    for transformer in transformers:
        for step in range(max_step + 1):
            pos = get_transformer_positions(transformer, step)
            if pos is None:
                continue

            ix, iy, d = pos
            if 0 <= ix < n and 0 <= iy < m:
                meeting_costs.setdefault(step, {}).setdefault((ix, iy), []).append(transformer['e'])

    # Aggregate costs by position and step
    aggregated = {}
    for step, pos_map in meeting_costs.items():
        for pos, costs in pos_map.items():
            key = (step, pos[0], pos[1])
            aggregated[key] = sum(costs)  # Plus it's in a meeting

    return aggregated

def solve_dp(n, m, meeting_costs):
    """
    Solve using DP: dp[i][j] = minimum energy to reach cell (i,j)
    """
    # Initialize dp table
    # dp[i][j] = minimum energy to reach (i,j)
    INF = float('inf')
    dp = [[INF] * m for _ in range(n)]
    dp[0][0] = 0

    # Precompute meeting costs by cell
    meeting_by_cell = {}
    for (step, i, j), cost in meeting_costs.items():
        meeting_by_cell[(i, j)] = meeting_by_cell.get((i, j), 0) + cost

    max_step = n + m - 2

    for s in range(1, max_step + 1):
        for i in range(min(s, n - 1)):
            j = s - i
            if 0 <= j < m:
                dp[i][j] = min(
                    dp[i][j],
                    dp[i][j - 1] + meeting_by_cell.get((i, j), 0)
                )

        for j in range(min(s, m - 1)):
            i = s - j
            if 0 <= i < n:
                dp[i][j] = min(
                    dp[i][j],
                    dp[i - 1][j] + meeting_by_cell.get((i, j), 0)
                )

    return dp[n - 1][m - 1]

