MOD = 10**9 + 7

def matrix_mul(A, B):
    C = [[0]*5 for _ in range(5)]
    for i in range(3):
        for k in range(5):
            if A[i][k]:
                for j in range(5):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matrix_pow(A, p):
    n = len(A)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = A
    while p:
        if p & 1:
            result = matrix_mul(result, base)
        base = matrix_mul(base, base)
        p >>= 1
    return result

