def bfs(n, m, grid, start, finish, moves):
    """BFS to find path from start to finish given move mappings."""
    queue = deque([(start, "")])
    visited = {start}

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == finish:
            return path

        for move_char, (dr, dc) in moves.items():
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append(((nr, nc), path + move_char))

    return ""


