    adj = defaultdict(set)
    for a, b in edges:
        adj[a].add(b)
        adj[b].add(a)

    valid_parents = set()

    for root in vertices:
        parent = {}
        depth = {}
        q = deque([root])
        depth[root] = 0
        visited = {root}

        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    parent[v] = u
                    depth[v] = depth[u] + 1
                    q.append(v)

