            p = parent[v]
            if p is None or p == v:
                continue

            # Check that all vertices have valid parent-child consistency
            all_consistent = True
            for u in vertices:
                if u == v:
                    continue

                pu = parent[u]
                if pu == v:
                    # u's parent was the removed vertex v
                    # After removal, u's children should be connected to p
                    continue
                elif pu is not None:
                    # Verify depth relationship is consistent
                    real_parent = parent[u]
                    if real_parent == v:
