            self._add(node['left'], l, mid, slope, intercept)
        else:
            if node['right'] is None:
                node['right'] = {'line': None, 'left': None, 'right': None}
            self._add(node['right'], mid + 1, r, slope, intercept)

    def query(self, x):
        return self._query(self.root, x)

    def _query(self, node, x):
        if node['line'] is None:
            return float('-inf')

        res = node['line'][0] * x + node['line'][1]

        if node['left'] is not None:
            res = max(res, self._query(node['left'], x))
        if node['right'] is not None:
            res = max(res, self._query(node['right'], x))

        return res

