    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(m):
        a, b = map(int, lines[1 + i].split())
        edges.append((i, a, b))  # (index, a, b)

    # Check if x is in the cyclic interval (start, end)
    def in_interval(start, end, x):
        if start < end:
            return start < x < end
        else:  # interval wraps around: [end+1, n-1] U [1, start-1]
            return x > end or x < start

    # Check if two edges cross (intersect except at endpoints)
    def is_crossing(e1, e2):
        a, b = e1[1], e1[2]
        c, d = e2[1], e2[2]

        # If they share an endpoint, they don't cross
        if a == c or a == d or b == c or b == d:
            return False

        # Both endpoints on same side of a-b arc = don't cross
        c_in_ab = in_interval(a, b, c)
        d_in_ab = in_interval(a, b, d)

        if c_in_ab == d_in_ab:
            return False

        # One on each side = they cross
        return True

    # Build conflict graph for crossing edges
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if is_crossing(edges[i], edges[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite (2-colorable)
    color = {}
    valid = True

    for i in range(m):
        if i not in color:
            color[i] = 0
            queue = [i]
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if v not in color:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        valid = False
                        break
                if not valid:
                    break
        if not valid:
            break

    if not valid:
        return "Impossible\n"

    # Color 0 = inner, Color 1 = outer
    result = ['i' if color[i] == 0 else 'o' for i in range(m)]
    return ''.join(result) + '\n'

