def solution(input_str):
    parts = input_str.strip().split('\n')
    n = int(parts[0])
    a = list(map(int, parts[1].split()))

    MOD = 10**9 + 7

    def get_sq_free(x):
        result = 1
        d = 2
        temp = x
        while d * d <= temp:
            if temp % d == 0:
                cnt = 0
                while temp % d == 0:
                    cnt += 1
                    temp //= d
                if cnt % 2 == 1:
                    result *= d
            d += 1
        if temp > 1:
            result *= temp
        return result

    groups = {}
    for x in a:
        gf = get_sq_free(x)
        if gf not in groups:
            groups[gf] = 0
        groups[gf] += 1

    group_sizes = [groups[gf] for gf in groups]
    num_groups = len(group_sizes)
    group_sizes.sort()

    def precompute_factorials(n_max):
        fact = [1] * (n_max + 1)
        inv_fact = [1] * (n_max + 1)
        for i in range(2, n_max + 1):
            fact[i] = (fact[i-1] * i) % MOD

        inv_fact[n_max] = pow(fact[n_max], MOD - 2, MOD)
        for i in range(n_max - 1, -1, -1):
            inv_fact[i] = (inv_fact[i+1] * (i + 1)) % MOD

        return fact, inv_fact

    fact, inv_fact = precompute_factorials(n)

    def C(n, k):
        if k < 0 or k > n:
            return 0
        num = fact[n]
        den = (inv_fact[k] * inv_fact[n - k]) % MOD
        return (num * den) % MOD

    dp = [0] * (n + 1)
    dp[0] = 1

    for g in group_sizes:
        for j in range(n, -1, -1):
            if dp[j] == 0:
                continue

            new_dp = [0] * (n + 1)
            current_open = j

            for new_open_val in range(min(g + 1, current_open + 1)):
                if new_open_val > current_open:
                    continue

                remaining_slots = n - j - new_open_val
                left_to_place = g - new_open_val

                if left_to_place < 0 or remaining_slots < left_to_place:
                    continue

                ways = C(current_open, new_open_val)
                ways = (ways * C(remaining_slots, left_to_place)) % MOD
                ways = (ways * fact[left_to_place]) % MOD
                ways = (ways * fact[new_open_val]) % MOD

                next_open = current_open + new_open_val

                if next_open <= n:
                    term = (dp[j] * ways) % MOD
                    new_dp[next_open] = (new_dp[next_open] + term) % MOD

            dp = new_dp

    return str(sum(dp) % MOD)

def bfs(start, adj, n):
    dist = [-1] * (n + 1)
    dist[start] = 0
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

