    for i in range(2, n + 1):
        log[i] = log[i // 2] + 1

    # Build sparse table for range minimum and maximum
    height = log[n] + 1
    st_min = [[float('inf')] * n for _ in range(height)]
    st_max = [[float('-inf')] * n for _ in range(height)]

    for i in range(n):
        st_min[0][i] = x[i]
        st_max[0][i] = x[i]

    for j in range(1, height):
        for i in range(n - (1 << j) + 1):
            mid = i + (1 << (j - 1))
            st_min[j][i] = min(st_min[j-1][i], st_min[j-1][mid])
            st_max[j][i] = max(st_max[j-1][i], st_max[j-1][mid])

    def query_min(l, r):
        length = r - l + 1
        k = 0
        while (1 << (k + 1)) <= length:
            k += 1
        return min(st_min[k][l], st_min[k][r - (1 << k) + 1])

    def query_max(l, r):
        length = r - l + 1
        k = 0
        while (1 << (k + 1)) <= length:
            k += 1
        return max(st_max[k][l], st_max[k][r - (1 << k) + 1])

    results = []
    for k_val in k_values:
        max_diff = w - k_val
        cuts = 0
        i = 0

        while i < n:
            cuts += 1
            # Find the longest valid range starting at i
            j = i + 1
            while j < n:
                if query_max(i, j) - query_min(i, j) <= max_diff:
                    j += 1
                else:
                    break
            i = j

        results.append(cuts)

    return '\n'.join(map(str, results))

